<?php
require 'includes/functions.php';$title='Panier';$base='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if(isset($_POST['remove']))unset($_SESSION['cart'][(int)$_POST['remove']]);else foreach(($_POST['qty']??[]) as $id=>$q){$id=(int)$id;$q=(int)$q;if($q<=0)unset($_SESSION['cart'][$id]);else $_SESSION['cart'][$id]=min(99,$q);}flash('Panier mis à jour.');go('cart.php');}
$cart=$_SESSION['cart']??[];$items=[];$total=0;if($cart){$ids=array_map('intval',array_keys($cart));$marks=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT p.*,(SELECT image_path FROM product_images WHERE product_id=p.id ORDER BY is_main DESC,id LIMIT 1) image_path FROM products p WHERE p.id IN ($marks)");$s->execute($ids);foreach($s->fetchAll() as $p){$q=min((int)$cart[$p['id']],(int)$p['stock']);if(!$q)continue;$p['qty']=$q;$p['line']=$q*$p['price'];$total+=$p['line'];$items[]=$p;}}
require 'includes/header.php';?><section class="banner"><div class="container"><small>AVANT LE COUP D'ENVOI</small><h1>MON PANIER</h1></div></section><section class="container section"><?php if(!$items):?><div class="empty"><h2>Ton panier est vide</h2><a class="btn" href="shop.php">Explorer la boutique</a></div><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="cartlayout"><div><?php foreach($items as $p):?><div class="cartrow"><img src="<?=e(img($p))?>"><div><b><?=e($p['name'])?></b><p><?=money($p['price'])?></p><label>Qté <input type="number" min="0" max="<?=(int)$p['stock']?>" name="qty[<?=(int)$p['id']?>]" value="<?=(int)$p['qty']?>"></label></div><strong><?=money($p['line'])?></strong><button name="remove" value="<?=(int)$p['id']?>" class="remove">×</button></div><?php endforeach?><button class="btn secondary" name="update" value="1">Mettre à jour</button></div><aside class="summary"><h2>Résumé</h2><p>Sous-total <b><?=money($total)?></b></p><hr><h3>Total : <?=money($total)?></h3><a class="btn full" href="checkout.php">PASSER LA COMMANDE</a></aside></div></form><?php endif?></section><?php require 'includes/footer.php';?>
